package com.d104.pnt.ui.game.playimport androidx.lifecycle.SavedStateHandleimport androidx.lifecycle.ViewModelimport androidx.lifecycle.viewModelScopeimport com.d104.pnt.data.repository.AuthRepositoryimport com.d104.pnt.data.repository.GameSessionEventimport com.d104.pnt.data.repository.GameSessionRepositoryimport com.d104.pnt.domain.model.GameRoleimport com.d104.pnt.navigation.NavArgsimport com.d104.pnt.util.socket.GameSocketManagerimport dagger.hilt.android.lifecycle.HiltViewModelimport kotlinx.coroutines.delayimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.flow.firstimport kotlinx.coroutines.launchimport timber.log.Timberimport javax.inject.Inject@HiltViewModelclass GameRoleViewModel @Inject constructor(    private val authRepository: AuthRepository,    private val gameSocketManager: GameSocketManager,    private val savedStateHandle: SavedStateHandle,    private val gameSessionRepository: GameSessionRepository) : ViewModel() {    private val roomId: Long = savedStateHandle.get<Long>(NavArgs.ROOM_ID) ?: 0L    private val roleName: String = savedStateHandle.get<String>(NavArgs.ROLE) ?: "THIEF"    val role: GameRole = GameRole.fromName(roleName)    private val _flowStatus = MutableStateFlow<GameFlowStatus>(GameFlowStatus.RoleReveal(role))    val flowStatus = _flowStatus.asStateFlow()    init {        gameSessionRepository.connectAndJoin(roomId)        Timber.d("RoomId: $roomId")        observeRepositoryEvents()    }    private fun observeRepositoryEvents() {        viewModelScope.launch {            gameSessionRepository.eventFlow.collect { event ->                when (event) {                    is GameSessionEvent.GameStarted -> {                        Timber.d("🚀 레포지토리에서 게임 시작 신호 수신!")                        _flowStatus.value = GameFlowStatus.CountDown(event.gameId)                    }                    is GameSessionEvent.GameEnded -> {                        Timber.d("레포지토리에서 게임 종료 신호 수신!")                    }                    is GameSessionEvent.ErrorOccurred -> {                        Timber.e("레포지토리에서 에러 발생: ${event.message}")                    }                }            }        }    }//    private fun setupListeners() {//        // Join 성공 확인 (로그용)//        gameSocketManager.setOnJoinedRoom { gameId, memberId, message ->//        }////        // get will start game//        gameSocketManager.setOnWillStartGame { gameId, willStartAt ->//            Timber.d("⏰ get will start game 수신 (무시) - gameId: $gameId, willStartAt: $willStartAt")//        }////        // get start game - 도둑 도망 화면으로 이동//        gameSocketManager.setOnGameStarted { gameId, startTime ->//            Timber.d("🏁 게임 시작! - gameId: $gameId, startTime: $startTime")//            _flowStatus.value = GameFlowStatus.CountDown(gameId)//        }//    }////    private fun connectAndJoin() {//        viewModelScope.launch {//            try {//                val token = authRepository.getAccessToken().first()//                if (token.isEmpty()) {//                    Timber.e("❌ 토큰이 비어있음")//                    return@launch//                }////                // 게임 소켓 연결 (백그라운드)//                Timber.d("🔌 게임 소켓 연결 시도...")//                gameSocketManager.connect(token)////                // 연결 대기//                var retryCount = 0//                while (!gameSocketManager.isConnected() && retryCount < 50) {//                    delay(100)//                    retryCount++//                }////                if (!gameSocketManager.isConnected()) {//                    Timber.e("❌ 게임 소켓 연결 실패")//                    return@launch//                }////                // 게임 입장//                gameSocketManager.joinGame(roomId)////            } catch (e: Exception) {//                Timber.e(e, "❌ 게임 연결 중 오류 발생")//            }//        }//    }}sealed class GameFlowStatus {    data class RoleReveal(val role: GameRole) : GameFlowStatus()    data class CountDown(val gameId: Long) : GameFlowStatus()}